<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sorting Algorithm Visualizer</title>
  <style>
    :root {
      --bg-color: #0f172a;
      --panel-bg: #1e293b;
      --text-color: #f8fafc;
      --text-muted: #94a3b8;
      --bar-default: #38bdf8;
      --bar-active: #f59e0b;
      --bar-sorted: #10b981;
      --primary: #6366f1;
      --primary-hover: #4f46e5;
      --button-bg: #334155;
      --button-hover: #475569;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    }

    body {
      background-color: var(--bg-color);
      color: var(--text-color);
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: 2rem 1rem;
    }

    header {
      text-align: center;
      margin-bottom: 1.5rem;
    }

    h1 {
      font-size: 1.75rem;
      font-weight: 700;
      letter-spacing: -0.025em;
      margin-bottom: 0.25rem;
    }

    p.subtitle {
      color: var(--text-muted);
      font-size: 0.9rem;
    }

    .main-card {
      background-color: var(--panel-bg);
      border-radius: 12px;
      padding: 1.5rem;
      width: 100%;
      max-width: 860px;
      box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
      display: flex;
      flex-direction: column;
      gap: 1.5rem;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
    }

    .btn-group {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

    button {
      background-color: var(--button-bg);
      color: var(--text-color);
      border: 1px solid rgba(255, 255, 255, 0.1);
      padding: 0.5rem 1rem;
      border-radius: 6px;
      font-size: 0.875rem;
      font-weight: 600;
      cursor: pointer;
      transition: background-color 0.15s ease, transform 0.05s ease;
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
    }

    button:hover {
      background-color: var(--button-hover);
    }

    button:active {
      transform: translateY(1px);
    }

    button#sort {
      background-color: var(--primary);
      border-color: var(--primary);
    }

    button#sort:hover {
      background-color: var(--primary-hover);
    }

    .speed-control {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.875rem;
      color: var(--text-muted);
    }

    .speed-control input[type="range"] {
      cursor: pointer;
      accent-color: var(--primary);
    }

    #bars {
      background-color: #0b1120;
      border: 1px solid rgba(255, 255, 255, 0.05);
      border-radius: 8px;
      height: 380px;
      width: 100%;
      display: flex;
      align-items: flex-end;
      justify-content: center;
      padding: 1rem;
      gap: 4px;
      overflow: hidden;
      position: relative;
    }

    .bar {
      flex: 1;
      max-width: 48px;
      min-width: 2px;
      background-color: var(--bar-default);
      border-radius: 4px 4px 0 0;
      transition: height 0.08s ease, background-color 0.08s ease;
      position: relative;
    }

    .bar.active {
      background-color: var(--bar-active) !important;
    }

    .bar.sorted {
      background-color: var(--bar-sorted) !important;
    }

    .status-bar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 0.8rem;
      color: var(--text-muted);
      border-top: 1px solid rgba(255, 255, 255, 0.08);
      padding-top: 0.75rem;
    }
  </style>
</head>
<body>
  <header>
    <h1>Sorting Visualizer</h1>
    <p class="subtitle">Step-by-step sorting algorithm animation</p>
  </header>

  <main class="main-card">
    <div class="controls">
      <div class="btn-group">
        <button id="sort">Sort</button>
        <button id="shuffle">Shuffle</button>
        <button id="reset">Reset</button>
      </div>
      <div class="speed-control">
        <label for="speed">Speed:</label>
        <input type="range" id="speed" min="1" max="100" value="70">
      </div>
    </div>

    <div id="bars"></div>

    <div class="status-bar">
      <span id="status-text">Ready</span>
      <span id="array-size">Size: 0</span>
    </div>
  </main>

  <script>
    (function () {
      let currentArray = [45, 20, 85, 10, 65, 30, 95, 70, 40, 15, 60, 90, 25, 80, 50, 35, 75, 5, 55, 100];
      let initialArray = [...currentArray];
      let isAnimating = false;
      let animationTimer = null;

      // Internal sort state for step-by-step bubble sort
      let sortState = {
        i: 0,
        j: 0,
        swapped: false,
        activeIndices: []
      };

      const barsContainer = document.getElementById('bars');
      const sortBtn = document.getElementById('sort');
      const shuffleBtn = document.getElementById('shuffle');
      const resetBtn = document.getElementById('reset');
      const speedInput = document.getElementById('speed');
      const statusText = document.getElementById('status-text');
      const arraySizeText = document.getElementById('array-size');

      function resetSortState() {
        sortState = {
          i: 0,
          j: 0,
          swapped: false,
          activeIndices: []
        };
      }

      function isSorted(arr) {
        for (let i = 0; i < arr.length - 1; i++) {
          if (arr[i] > arr[i + 1]) return false;
        }
        return true;
      }

      function render() {
        barsContainer.innerHTML = '';
        const len = currentArray.length;
        arraySizeText.textContent = `Size: ${len}`;

        if (len === 0) return;

        const maxVal = Math.max(...currentArray, 1);
        const minVal = Math.min(...currentArray, 0);
        const range = maxVal - minVal || 1;
        const allSorted = isSorted(currentArray);

        currentArray.forEach((val, idx) => {
          const bar = document.createElement('div');
          bar.className = 'bar';

          const percentage = Math.max(((val - minVal) / range) * 94 + 6, 6);
          bar.style.height = `${percentage}%`;
          bar.title = `${val}`;

          if (allSorted) {
            bar.classList.add('sorted');
          } else if (sortState.activeIndices.includes(idx)) {
            bar.classList.add('active');
          }

          barsContainer.appendChild(bar);
        });
      }

      function stopAnimation() {
        if (animationTimer) {
          clearTimeout(animationTimer);
          animationTimer = null;
        }
        isAnimating = false;
        sortBtn.textContent = 'Sort';
      }

      function performStep() {
        if (isSorted(currentArray)) {
          sortState.activeIndices = [];
          render();
          statusText.textContent = 'Sorted!';
          return true;
        }

        const n = currentArray.length;
        if (n <= 1) {
          sortState.activeIndices = [];
          render();
          return true;
        }

        if (sortState.i >= n - 1) {
          sortState.i = 0;
          sortState.j = 0;
          sortState.swapped = false;
        }

        const j = sortState.j;
        sortState.activeIndices = [j, j + 1];

        if (currentArray[j] > currentArray[j + 1]) {
          const temp = currentArray[j];
          currentArray[j] = currentArray[j + 1];
          currentArray[j + 1] = temp;
          sortState.swapped = true;
        }

        sortState.j++;
        if (sortState.j >= n - 1 - sortState.i) {
          sortState.j = 0;
          sortState.i++;
          sortState.swapped = false;
        }

        const completed = isSorted(currentArray);
        if (completed) {
          sortState.activeIndices = [];
        }

        render();
        statusText.textContent = completed ? 'Sorted!' : 'Sorting...';
        return completed;
      }

      function runAnimation() {
        if (!isAnimating) return;

        const done = performStep();
        if (done) {
          stopAnimation();
        } else {
          const speedVal = parseInt(speedInput.value, 10);
          const delay = Math.max(5, Math.floor(400 - (speedVal / 100) * 390));
          animationTimer = setTimeout(runAnimation, delay);
        }
      }

      function startSortAnimation() {
        if (isSorted(currentArray)) {
          return;
        }
        if (isAnimating) {
          stopAnimation();
          statusText.textContent = 'Paused';
        } else {
          isAnimating = true;
          sortBtn.textContent = 'Pause';
          statusText.textContent = 'Sorting...';
          runAnimation();
        }
      }

      function shuffleArray() {
        stopAnimation();
        for (let i = currentArray.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [currentArray[i], currentArray[j]] = [currentArray[j], currentArray[i]];
        }
        initialArray = [...currentArray];
        resetSortState();
        render();
        statusText.textContent = 'Shuffled';
      }

      function resetArray() {
        stopAnimation();
        currentArray = [...initialArray];
        resetSortState();
        render();
        statusText.textContent = 'Reset';
      }

      sortBtn.addEventListener('click', startSortAnimation);
      shuffleBtn.addEventListener('click', shuffleArray);
      resetBtn.addEventListener('click', resetArray);

      // Programmatic API for evaluation
      window.viz = {
        array() {
          return currentArray;
        },
        setArray(a) {
          stopAnimation();
          currentArray = a.slice();
          initialArray = a.slice();
          resetSortState();
          render();
          statusText.textContent = 'Array updated';
        },
        sortStep() {
          return performStep();
        },
        sorted() {
          return isSorted(currentArray);
        }
      };

      // Initial render
      render();
    })();
  </script>
</body>
</html>
